const MAX_VISIBLE_TAGS = 50;

const TAG_STATUS = {
  IDLE: "idle",
  LOADING: "loading",
  SUCCESS: "success",
  ERROR: "error",
};

const TAG_MESSAGES = {
  empty: "Tags list not available",
  error: "Unable to load tags",
  loading: "Loading tags...",
};

export { MAX_VISIBLE_TAGS, TAG_MESSAGES, TAG_STATUS };

import { MAX_VISIBLE_TAGS } from "./constants";
import TagPill from "./TagPill";

function TagList({ tags }) {
  return tags.slice(0, MAX_VISIBLE_TAGS).map((name) => (
    <TagPill key={name} name={name} />
  ));
}

export default TagList;

import getVisibleTags from "./getVisibleTags";
import TagPill from "./TagPill";

function TagList({ tags }) {
  return getVisibleTags(tags).map((name) => (
    <TagPill key={name} name={name} />
  ));
}

export default TagList;

